var fetchProductById = createBaseElysia().get("/:id", async ({ set: set2, log, params, cookie: { session } }) => {
  try {
    const { id } = params;
    let loggedInUserId = undefined;
    if (session && session.value) {
      try {
        const { user } = await validateSessionToken(session.value);
        loggedInUserId = user?.id;
      } catch (error2) {
        log.warn("Session validation failed");
      }
    }
    const product = await db.product.findUnique({
      where: {
        id
      },
      include: {
        categories: {
          include: {
            category: {
              select: {
                id: true,
                name: true
              }
            }
          }
        },
        tags: {
          select: {
            tag: {
              select: {
                id: true,
                name: true
              }
            }
          }
        },
        reviews: {
          select: {
            rating: true,
            description: true,
            user: {
              select: {
                id: true,
                name: true
              }
            }
          }
        },
        likes: {
          select: {
            id: true,
            userId: true
          }
        },
        images: {
          orderBy: {
            order: "asc"
          },
          select: {
            id: true,
            url: true,
            order: true
          }
        },
        seller: {
          include: {
            products: {
              select: {
                id: true,
                reviews: {
                  select: {
                    rating: true
                  }
                }
              }
            },
            _count: {
              select: {
                followers: true,
                products: true,
                reviews: true
              }
            }
          }
        },
        productViews: true
      }
    });
    if (!product) {
      set2.status = 404;
      return {
        status: "error",
        message: "Product not found"
      };
    }
    if (product.status === "DELETED") {
      set2.status = 404;
      return {
        status: "error",
        message: "Product not found or no longer available"
      };
    }
    await db.productView.create({
      data: {
        productId: id,
        userId: loggedInUserId
      }
    });
    const sellerReviews = product.seller.products.flatMap((p) => p.reviews);
    const averageRating = sellerReviews.length > 0 ? sellerReviews.reduce((sum, review) => sum + review.rating, 0) / sellerReviews.length : null;
    const isLiked = loggedInUserId ? product.likes.some((like) => like.userId === loggedInUserId) : false;
    const viewCount = product.productViews.length;
    const transformedProduct = {
      ...product,
      tags: product.tags.map(({ tag }) => tag),
      likesCount: product.likes.length,
      isLiked,
      viewCount,
      seller: {
        id: product.seller.id,
        name: product.seller.name,
        userName: product.seller.userName,
        imageUrl: product.seller.imageUrl,
        bio: product.seller.bio,
        averageRating: averageRating ? Number(averageRating.toFixed(1)) : null,
        totalReviews: sellerReviews.length,
        followers: product.seller._count.followers
      }
    };
    set2.status = "OK";
    return {
      status: "success",
      message: "Product retrieved successfully",
      data: transformedProduct
    };
  } catch (error2) {
    log.error(error2);
    set2.status = 500;
    return {
      status: "error",
      message: "Failed to fetch product"
    };
  }
}, {
  params: t.Object({
    id: t.String()
  }),
  response: SingleProductResponseSchema,
  detail: {
    tags: ["Products"],
    summary: "Fetch product by id",
    description: "Fetch a single product by ID with all its related data, including detailed seller information, whether the logged-in user has liked it, and recording a product view"
  }
});

