// src/controllers/products/remove-product-image.ts
var removeProductImage = createBaseElysia().delete(":id/images/:imageId", async ({ set: set2, log, cookie: { session }, params }) => {
  try {
    if (!session.value) {
      set2.status = "Bad Request";
      return { status: "error", message: "Session not found" };
    }
    const { session: dbSession, user } = await validateSessionToken(session.value);
    if (!dbSession || !user) {
      set2.status = "Unauthorized";
      return { status: "error", message: "Invalid session" };
    }
    const image = await db.productImage.findUnique({
      where: { id: params.imageId },
      include: { product: true }
    });
    if (!image) {
      set2.status = "Not Found";
      return { status: "error", message: "Image not found" };
    }
    if (image.product.sellerId !== user.id) {
      set2.status = "Forbidden";
      return {
        status: "error",
        message: "You don't have permission to modify this product"
      };
    }
    await db.productImage.delete({
      where: { id: params.imageId }
    });
    await db.productImage.updateMany({
      where: {
        productId: params.id,
        order: { gt: image.order }
      },
      data: {
        order: { decrement: 1 }
      }
    });
    return {
      status: "success",
      message: "Image removed successfully"
    };
  } catch (error2) {
    log.error("remove product image error:", error2);
    set2.status = 500;
    return {
      status: "error",
      message: "An error occurred while removing the image"
    };
  }
}, {
  params: t.Object({
    id: t.String(),
    imageId: t.String()
  }),
  detail: {
    tags: ["Products"],
    summary: "Remove product image",
    description: "Remove an image from a product"
  }
});

