// src/controllers/user/reactivate-account.ts
var reactivateAccount = createBaseElysia().put("/:id/reactivate", async ({ params, set: set2, log, cookie: { session } }) => {
  try {
    if (!session.value) {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "Session not found"
      };
    }
    const { session: dbSession, user } = await validateSessionToken(session.value);
    if (!dbSession || !user) {
      set2.status = "Unauthorized";
      return {
        status: "error",
        message: "Invalid session"
      };
    }
    if (user.id !== params.id) {
      set2.status = "Forbidden";
      return {
        status: "error",
        message: "You can only reactivate your own account"
      };
    }
    if (!user.isDeactivated) {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "Account is not deactivated"
      };
    }
    await db.$transaction(async (tx) => {
      await tx.user.update({
        where: { id: user.id },
        data: {
          isDeactivated: false,
          deactivatedAt: null
        }
      });
      await tx.product.updateMany({
        where: {
          sellerId: user.id,
          status: { not: "DELETED" }
        },
        data: {
          isAvailable: true
        }
      });
    });
    set2.status = "OK";
    return {
      status: "success",
      message: "Account successfully reactivated"
    };
  } catch (error2) {
    log.error("Account reactivation error:", error2);
    set2.status = 500;
    return {
      status: "error",
      message: "An error occurred while reactivating the account"
    };
  }
}, {
  params: t.Object({
    id: t.String()
  }),
  detail: {
    tags: ["Users"],
    summary: "Reactivate account",
    description: "Reactivate a previously deactivated user account"
  }
});

