// src/controllers/cart/add-product-to-cart.ts
var addToCart = createBaseElysia().post("", async ({ body, set: set2, log, cookie: { session } }) => {
  try {
    if (!session.value) {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "Session not found"
      };
    }
    const { session: dbSession, user } = await validateSessionToken(session.value);
    if (!dbSession || !user) {
      set2.status = "Unauthorized";
      return {
        status: "error",
        message: "Invalid session"
      };
    }
    const product = await db.product.findUnique({
      where: { id: body.productId }
    });
    if (!product) {
      set2.status = "Not Found";
      return {
        status: "error",
        message: "Product not found"
      };
    }
    if (product.sellerId === user.id) {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "You cannot add your own product to your cart"
      };
    }
    if (!product.isAvailable || product.status !== "ACTIVE") {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "This product is currently unavailable"
      };
    }
    let cart = await db.cart.findUnique({
      where: { userId: user.id }
    });
    if (!cart) {
      cart = await db.cart.create({
        data: { userId: user.id }
      });
    }
    const existingItem = await db.cartItem.findUnique({
      where: {
        cartId_productId: {
          cartId: cart.id,
          productId: body.productId
        }
      }
    });
    const newQuantity = existingItem ? existingItem.quantity + body.quantity : body.quantity;
    if (newQuantity > product.quantity) {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: `Only ${product.quantity} ${product.quantity === 1 ? "item" : "items"} available for "${product.title}".`
      };
    }
    if (existingItem) {
      await db.cartItem.update({
        where: { id: existingItem.id },
        data: {
          quantity: newQuantity,
          updatedAt: new Date
        }
      });
    } else {
      await db.cartItem.create({
        data: {
          cartId: cart.id,
          productId: body.productId,
          quantity: body.quantity
        }
      });
    }
    const updatedCart = await db.cart.findUnique({
      where: { id: cart.id },
      include: {
        items: {
          include: {
            product: {
              include: {
                images: true,
                seller: {
                  select: {
                    id: true,
                    name: true,
                    userName: true,
                    imageUrl: true
                  }
                }
              }
            }
          }
        }
      }
    });
    set2.status = "OK";
    return {
      status: "success",
      message: "Item added to cart successfully",
      data: updatedCart
    };
  } catch (error2) {
    log.error("Add to cart error:", error2);
    set2.status = 500;
    return {
      status: "error",
      message: "An error occurred while adding the item to cart"
    };
  }
}, {
  body: t.Object({
    productId: t.String(),
    quantity: t.Number({
      minimum: 1,
      maximum: 10,
      default: 1,
      error: "Quantity must be between 1 and 10 items."
    })
  }),
  detail: {
    tags: ["Cart"],
    summary: "Add to cart",
    description: "Add a product to the user's shopping cart"
  }
});

