// src/controllers/cart/get-cart.ts
var getCart = createBaseElysia().get("", async ({ set: set2, log, cookie: { session } }) => {
  try {
    if (!session.value) {
      set2.status = "Bad Request";
      return { status: "error", message: "Session not found" };
    }
    const { session: dbSession, user } = await validateSessionToken(session.value);
    if (!dbSession || !user) {
      set2.status = "Unauthorized";
      return { status: "error", message: "Invalid session" };
    }
    let cart = await db.cart.findUnique({
      where: { userId: user.id },
      include: {
        items: {
          include: {
            product: {
              include: {
                images: true,
                seller: {
                  select: {
                    id: true,
                    name: true,
                    userName: true,
                    imageUrl: true
                  }
                }
              }
            }
          }
        }
      }
    });
    if (!cart) {
      cart = await db.cart.create({
        data: {
          userId: user.id
        },
        include: {
          items: {
            include: {
              product: {
                include: {
                  images: true,
                  seller: {
                    select: {
                      id: true,
                      name: true,
                      userName: true,
                      imageUrl: true
                    }
                  }
                }
              }
            }
          }
        }
      });
    }
    const groupedBySellerItems = cart.items.reduce((result, item) => {
      const sellerId = item.product.seller.id;
      if (!result[sellerId]) {
        result[sellerId] = {
          seller: item.product.seller,
          items: []
        };
      }
      result[sellerId].items.push(item);
      return result;
    }, {});
    const sellerGroups = Object.values(groupedBySellerItems);
    return {
      status: "success",
      data: {
        id: cart.id,
        userId: cart.userId,
        createdAt: cart.createdAt,
        updatedAt: cart.updatedAt,
        sellerGroups,
        items: cart.items
      }
    };
  } catch (error2) {
    log.error("get cart error:", error2);
    set2.status = 500;
    return {
      status: "error",
      message: "An error occurred while fetching the cart"
    };
  }
}, {
  detail: {
    tags: ["Cart"],
    summary: "Get user's cart",
    description: "Retrieve the current user's shopping cart with items grouped by seller"
  }
});

