// src/ws/connections.ts
var activeConnections = new Map;
function addConnection(userId, ws) {
  const connection = {
    send: (data) => ws.send(data),
    close: () => ws.close()
  };
  activeConnections.set(userId, connection);
  console.log(`User ${userId} connected. Active connections: ${activeConnections.size}`);
}
function removeConnection(userId) {
  if (activeConnections.has(userId)) {
    activeConnections.delete(userId);
    console.log(`User ${userId} disconnected. Active connections: ${activeConnections.size}`);
  }
}
function getConnection(userId) {
  return activeConnections.get(userId);
}

// src/ws/broadcast.ts
function broadcastToUser(userId, event) {
  const connection = activeConnections.get(userId);
  if (connection) {
    try {
      connection.send(JSON.stringify(event));
      return true;
    } catch (error2) {
      console.error(`Error broadcasting to user ${userId}:`, error2);
      return false;
    }
  }
  return false;
}
function broadcastMessageEvent(event) {
  broadcastToUser(event.to, {
    type: event.type,
    from: event.from,
    conversationId: event.conversationId,
    data: event.data,
    timestamp: Date.now()
  });
  if (event.from && event.type === "NEW_MESSAGE") {
    broadcastToUser(event.from, {
      type: "MESSAGE_SENT",
      to: event.to,
      conversationId: event.conversationId,
      data: event.data,
      timestamp: Date.now()
    });
  }
}

