// src/ws/handler.ts
var wsHandler = createBaseElysia().ws("/ws/messages", {
  async open(ws) {
    try {
      const wsToken = ws.data.query.token;
      if (!wsToken) {
        ws.send(JSON.stringify({
          type: "error",
          message: "Authentication required"
        }));
        ws.close();
        return;
      }
      const tokenRecord = await db.wsToken.findUnique({
        where: { token: wsToken },
        include: { user: true }
      });
      if (!tokenRecord || tokenRecord.expiresAt < new Date) {
        ws.send(JSON.stringify({
          type: "error",
          message: "Invalid or expired token"
        }));
        ws.close();
        return;
      }
      addConnection(tokenRecord.user.id, ws);
      ws.send(JSON.stringify({
        type: "connected",
        userId: tokenRecord.user.id,
        timestamp: Date.now()
      }));
    } catch (error2) {
      console.error("WebSocket connection error:", error2);
      ws.send(JSON.stringify({
        type: "error",
        message: "Connection error"
      }));
      ws.close();
    }
  },
  message(ws, message) {
    try {
      if (typeof message === "string") {
        message = JSON.parse(message);
      }
      if (typeof message !== "object" || message === null) {
        return;
      }
      if ("type" in message) {
        if (message.type === "TYPING" || message.type === "CUSTOM_EVENT") {
          const { from, to, conversationId } = message;
          if (from && to && conversationId) {
            const connection = getConnection(to);
            if (connection) {
              connection.send(JSON.stringify({
                type: message.type,
                from,
                conversationId,
                payload: message.payload || {},
                timestamp: Date.now()
              }));
            }
          }
        }
      }
    } catch (error2) {
      console.error("Error handling WebSocket message:", error2);
    }
  },
  close(ws) {
    try {
      for (const [userId, conn] of activeConnections.entries()) {
        if (conn === ws) {
          removeConnection(userId);
          break;
        }
      }
    } catch (error2) {
      console.error("Error handling WebSocket close:", error2);
    }
  }
});

