// src/controllers/search/search.ts
var parseIntSafely = (value, defaultValue) => {
  if (!value)
    return defaultValue;
  const parsed = parseInt(value, 10);
  return isNaN(parsed) ? defaultValue : Math.max(1, parsed);
};
var parseFloatSafely = (value) => {
  if (!value)
    return;
  const parsed = parseFloat(value);
  return isNaN(parsed) ? undefined : parsed;
};
var buildProductFilter = (params) => {
  const { searchQuery, category, minPrice, maxPrice, condition, gender } = params;
  const filter = {
    status: "ACTIVE",
    isAvailable: true
  };
  if (searchQuery.trim()) {
    filter.OR = [
      { title: { contains: searchQuery, mode: "insensitive" } },
      { description: { contains: searchQuery, mode: "insensitive" } },
      { brand: { name: { contains: searchQuery, mode: "insensitive" } } },
      {
        categories: {
          some: {
            category: { name: { contains: searchQuery, mode: "insensitive" } }
          }
        }
      },
      {
        tags: {
          some: {
            tag: { name: { contains: searchQuery, mode: "insensitive" } }
          }
        }
      }
    ];
  }
  if (category) {
    filter.categories = {
      some: {
        category: { name: { equals: category, mode: "insensitive" } }
      }
    };
  }
  const minPriceValue = parseFloatSafely(minPrice);
  const maxPriceValue = parseFloatSafely(maxPrice);
  if (minPriceValue !== undefined || maxPriceValue !== undefined) {
    filter.basePrice = {};
    if (minPriceValue !== undefined)
      filter.basePrice.gte = minPriceValue;
    if (maxPriceValue !== undefined)
      filter.basePrice.lte = maxPriceValue;
  }
  if (condition)
    filter.condition = condition;
  if (gender)
    filter.gender = gender;
  return filter;
};
var buildUserFilter = (searchQuery) => {
  const filter = {
    isDeactivated: false
  };
  if (searchQuery.trim()) {
    filter.OR = [
      { name: { contains: searchQuery, mode: "insensitive" } },
      { userName: { contains: searchQuery, mode: "insensitive" } }
    ];
  }
  return filter;
};
var searchProducts = async (params) => {
  const { filter, skip: skip2, take, userId } = params;
  const [products, total] = await Promise.all([
    db.product.findMany({
      where: filter,
      include: {
        images: {
          orderBy: { order: "asc" },
          select: { id: true, url: true, order: true }
        },
        categories: {
          include: {
            category: { select: { id: true, name: true } }
          }
        },
        brand: {
          select: { id: true, name: true }
        },
        seller: {
          select: { id: true, name: true, userName: true, imageUrl: true }
        },
        tags: {
          include: { tag: true }
        },
        _count: {
          select: { likes: true }
        },
        ...userId ? {
          likes: {
            where: { userId },
            select: { id: true }
          }
        } : {}
      },
      orderBy: [{ createdAt: "desc" }],
      skip: skip2,
      take
    }),
    db.product.count({ where: filter })
  ]);
  return {
    items: products.map((product) => {
      const { _count, tags, likes, categories, ...rest } = product;
      return {
        ...rest,
        categories: categories.map(({ productId, categoryId, category }) => ({
          productId,
          categoryId,
          category
        })),
        tags: tags.map(({ tag }) => tag),
        likesCount: _count.likes,
        ...userId ? { isLiked: likes && likes.length > 0 } : {}
      };
    }),
    total
  };
};
var searchUsers = async (params) => {
  const { filter, skip: skip2, take, userId } = params;
  const [users, total] = await Promise.all([
    db.user.findMany({
      where: filter,
      select: {
        id: true,
        name: true,
        userName: true,
        imageUrl: true,
        bio: true,
        _count: {
          select: {
            products: {
              where: { status: "ACTIVE", isAvailable: true }
            },
            followers: true,
            following: true
          }
        },
        ...userId ? {
          followers: {
            where: { followerId: userId },
            select: { id: true }
          }
        } : {}
      },
      orderBy: {
        followers: { _count: "desc" }
      },
      skip: skip2,
      take
    }),
    db.user.count({ where: filter })
  ]);
  return {
    items: users.map((user) => {
      const { _count, followers, ...rest } = user;
      return {
        ...rest,
        productsCount: _count.products,
        followersCount: _count.followers,
        followingCount: _count.following,
        ...userId ? { isFollowing: followers && followers.length > 0 } : {}
      };
    }),
    total
  };
};
var searchEndpoint = createBaseElysia().get("", async ({ set: set2, log, query, cookie: { session } }) => {
  try {
    const {
      q = "",
      type: type2,
      page = "1",
      limit = "10",
      category,
      minPrice,
      maxPrice,
      condition,
      gender
    } = query;
    const searchQuery = q.trim();
    const currentPage = parseIntSafely(page, 1);
    const perPage = Math.min(parseIntSafely(limit, 10), 50);
    const skip2 = (currentPage - 1) * perPage;
    let userId = null;
    if (session?.value) {
      try {
        const { user } = await validateSessionToken(session.value);
        userId = user?.id || null;
      } catch (error2) {
        log.error("Session validation error:", error2);
      }
    }
    const results = {
      products: { items: [], total: 0 },
      users: { items: [], total: 0 }
    };
    const searchTypes = type2 ? [type2] : ["products", "users"];
    if (searchTypes.includes("products")) {
      const productFilter = buildProductFilter({
        searchQuery,
        category,
        minPrice,
        maxPrice,
        condition,
        gender
      });
      results.products = await searchProducts({
        filter: productFilter,
        skip: skip2,
        take: perPage,
        userId: userId || undefined
      });
    }
    if (searchTypes.includes("users")) {
      const userFilter = buildUserFilter(searchQuery);
      results.users = await searchUsers({
        filter: userFilter,
        skip: skip2,
        take: perPage,
        userId: userId || undefined
      });
    }
    let primaryResultType = "products";
    if (type2) {
      primaryResultType = type2;
    } else {
      primaryResultType = results.users.total > results.products.total ? "users" : "products";
    }
    const totalForPagination = results[primaryResultType].total;
    const lastPage = Math.ceil(totalForPagination / perPage);
    return {
      status: "success",
      message: "Search completed successfully",
      data: {
        query: searchQuery,
        primaryResultType,
        products: results.products,
        users: results.users,
        pagination: {
          total: totalForPagination,
          lastPage,
          currentPage,
          perPage,
          prev: currentPage > 1 ? currentPage - 1 : null,
          next: currentPage < lastPage ? currentPage + 1 : null
        }
      }
    };
  } catch (error2) {
    log.error("Search endpoint error:", error2);
    set2.status = 500;
    return {
      status: "error",
      message: "Failed to perform search",
      error: error2 instanceof Error ? error2.message : "Unknown error"
    };
  }
}, {
  query: t.Object({
    q: t.Optional(t.String()),
    type: t.Optional(t.Union([t.Literal("products"), t.Literal("users")])),
    page: t.Optional(t.String()),
    limit: t.Optional(t.String()),
    category: t.Optional(t.String()),
    minPrice: t.Optional(t.String()),
    maxPrice: t.Optional(t.String()),
    condition: t.Optional(t.Union([
      t.Literal("NEW"),
      t.Literal("OPEN_BOX"),
      t.Literal("LIKE_NEW"),
      t.Literal("LIGHTLY_USED"),
      t.Literal("FAIRLY_USED"),
      t.Literal("HEAVILY_USED")
    ])),
    gender: t.Optional(t.Union([t.Literal("MEN"), t.Literal("WOMEN"), t.Literal("UNISEX")]))
  }),
  detail: {
    tags: ["Search"],
    summary: "Unified search endpoint",
    description: "Search across products and users with multiple filtering options"
  }
});

