var deleteBrand = createBaseElysia().delete("/brands/:id", async ({ params, set: set2, log, cookie: { session } }) => {
  try {
    if (!session.value) {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "Session not found"
      };
    }
    const { session: dbSession, user } = await validateSessionToken(session.value);
    if (!dbSession || !user) {
      set2.status = "Unauthorized";
      return {
        status: "error",
        message: "Invalid session"
      };
    }
    const brand = await db.brand.findFirst({
      where: {
        id: params.id,
        ownerId: user.id
      },
      include: {
        _count: {
          select: {
            products: true
          }
        }
      }
    });
    if (!brand) {
      set2.status = "Not Found";
      return {
        status: "error",
        message: "Brand not found or you don't have permission"
      };
    }
    if (brand.status !== "DRAFT") {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "Only draft brands can be deleted"
      };
    }
    if (brand._count.products > 0) {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "Cannot delete brand with associated products"
      };
    }
    await db.brand.delete({
      where: { id: params.id }
    });
    set2.status = "OK";
    return {
      status: "success",
      message: "Brand deleted successfully"
    };
  } catch (error2) {
    log.error("Brand deletion error:", error2);
    set2.status = 500;
    return {
      status: "error",
      message: "An error occurred while deleting brand"
    };
  }
}, {
  params: t.Object({
    id: t.String()
  }),
  detail: {
    tags: ["Brands"],
    summary: "Delete brand",
    description: "Delete brand (only draft brands with no products)"
  }
});

