var submitBrandForVerification = createBaseElysia().post("/brands/:id/submit-verification", async ({ params, body, set: set2, log, cookie: { session } }) => {
  try {
    if (!session.value) {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "Session not found"
      };
    }
    const { session: dbSession, user } = await validateSessionToken(session.value);
    if (!dbSession || !user) {
      set2.status = "Unauthorized";
      return {
        status: "error",
        message: "Invalid session"
      };
    }
    const brand = await db.brand.findFirst({
      where: {
        id: params.id,
        ownerId: user.id
      }
    });
    if (!brand) {
      set2.status = "Not Found";
      return {
        status: "error",
        message: "Brand not found or you don't have permission"
      };
    }
    if (brand.status === "VERIFIED") {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "Brand is already verified"
      };
    }
    if (brand.status === "PENDING") {
      set2.status = "Bad Request";
      return {
        status: "error",
        message: "Brand is already pending verification"
      };
    }
    const updatedBrand = await db.brand.update({
      where: { id: params.id },
      data: {
        name: body.name,
        description: body.description,
        contactAddress: body.contactAddress,
        businessPhoneNumber: body.businessPhoneNumber,
        logoUrl: body.logoUrl,
        status: "PENDING"
      }
    });
    if (body.certificationFiles && body.certificationFiles.length > 0) {
      await db.brandCertification.createMany({
        data: body.certificationFiles.map((file) => ({
          brandId: params.id,
          fileUrl: file.fileUrl,
          fileName: file.fileName,
          fileType: file.fileType,
          fileSize: file.fileSize
        }))
      });
    }
    await db.notification.create({
      data: {
        userId: user.id,
        type: "BRAND_VERIFICATION_STATUS",
        content: `Your brand "${brand.name}" has been submitted for verification`
      }
    });
    set2.status = "OK";
    return {
      status: "success",
      message: "Brand submitted for verification",
      data: updatedBrand
    };
  } catch (error2) {
    log.error("Brand verification submission error:", error2);
    set2.status = 500;
    return {
      status: "error",
      message: "An error occurred while submitting brand for verification"
    };
  }
}, {
  params: t.Object({
    id: t.String()
  }),
  body: t.Object({
    name: t.String({ minLength: 2, maxLength: 100 }),
    description: t.Optional(t.String({ maxLength: 1000 })),
    contactAddress: t.Optional(t.String({ maxLength: 500 })),
    businessPhoneNumber: t.Optional(t.String({ maxLength: 20 })),
    logoUrl: t.Optional(t.String()),
    certificationFiles: t.Optional(t.Array(t.Object({
      fileUrl: t.String(),
      fileName: t.String(),
      fileType: t.String(),
      fileSize: t.Number()
    })))
  }),
  detail: {
    tags: ["Brands"],
    summary: "Submit brand for verification",
    description: "Submit brand registration for admin verification"
  }
});

