function resolvePickupAddressForOrderItems(items) {
  const sellers = new Map;
  for (const item of items) {
    const sellerId = item.product?.sellerId;
    if (!sellerId) {
      continue;
    }
    sellers.set(sellerId, item.product?.seller);
  }
  if (sellers.size === 0) {
    throw new Error("Order items must include seller details for dispatch pickup");
  }
  if (sellers.size > 1) {
    throw new Error("Checkout currently supports one seller per order. Please split multi-seller carts into separate orders.");
  }
  const seller = sellers.values().next().value;
  const addresses2 = seller?.addresses || [];
  const pickupAddress = addresses2.find((address) => address.type === "PICKUP" && address.isDefault) || addresses2.find((address) => address.type === "PICKUP") || addresses2.find((address) => address.type === "SHIPPING" && address.isDefault) || addresses2.find((address) => address.type === "SHIPPING");
  if (!pickupAddress) {
    throw new Error("Seller needs a Lagos pickup address before this item can be checked out");
  }
  return pickupAddress;
}
function formatAddress(address) {
  return [address.street, address.landmark, address.city, address.state, address.country].filter(Boolean).join(", ");
}
function formatKwikDate(date2) {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: "Africa/Lagos",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false
  }).format(date2).replace(",", "");
}
function numberFromUnknown(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}
function normalizeLocationName(value) {
  return value.trim().toLowerCase().replace(/[^a-z0-9]+/g, " ").replace(/\s+/g, " ").trim();
}
function extractAmount(response) {
  return Number(response?.billBreakdown?.data?.NET_PAYABLE_AMOUNT || response?.billBreakdown?.data?.ORDER_PAYABLE_AMOUNT || response?.billBreakdown?.data?.PAYABLE_AMOUNT || response?.pricing?.data?.per_task_cost || response?.data?.per_task_cost || response?.data?.amount || 0);
}
function extractCurrency(response) {
  return response?.pricing?.data?.currency?.code || response?.data?.currency?.code || response?.data?.currency;
}
function extractExternalId(response) {
  return String(response?.data?.unique_order_id || response?.unique_order_id || "");
}
function extractTrackingId(response) {
  return String(response?.data?.deliveries?.[0]?.job_id || response?.data?.pickups?.[0]?.job_id || "");
}
function extractTrackingUrl(response) {
  return response?.data?.deliveries?.[0]?.result_tracking_link || response?.data?.pickups?.[0]?.result_tracking_link || response?.data?.job_status_check_link;
}
function extractProviderStatus(response) {
  return String(response?.data?.deliveries?.[0]?.job_status || response?.data?.pickups?.[0]?.job_status || response?.status || "");
}
function extractKwikJobIds(providerPayload) {
  const payload = providerPayload;
  return [
    ...payload?.data?.pickups || [],
    ...payload?.data?.deliveries || []
  ].map((job) => job?.job_id).filter(Boolean).map(String);
}
function getKwikDeliveryJob(providerResponse) {
  const jobs = providerResponse?.data?.orders || [];
  return jobs.find((job) => Number(job.job_type) === 1) || jobs[jobs.length - 1];
}
function extractMessage(response) {
  return response?.message || response?.error || response?.data?.message;
}
function getShipmentTimestampField(status) {
  if (status === "DISPATCHED" || status === "DISPATCH_REQUESTED")
    return "dispatchedAt";
  if (status === "ARRIVED")
    return "pickedUpAt";
  if (status === "DELIVERED")
    return "deliveredAt";
  if (status === "CANCELLED")
    return "cancelledAt";
  return null;
}
async function settleSellerWalletsForDeliveredOrder(orderId) {
  await db.$transaction(async (tx) => {
    const order = await tx.order.findUnique({
      where: { id: orderId },
      select: {
        status: true,
        subtotalAmount: true,
        commissionAmount: true,
        sellerPayoutAmount: true
      }
    });
    if (!order) {
      throw new Error("Order not found for seller settlement");
    }
    if (order.status !== "DELIVERED") {
      throw new Error("Seller settlement can only run after order delivery");
    }
    const unsettledItems = await tx.orderItem.findMany({
      where: {
        orderId,
        sellerSettledAt: null
      },
      include: {
        product: {
          select: {
            sellerId: true
          }
        }
      }
    });
    if (unsettledItems.length === 0) {
      return;
    }
    const subtotalAmount = Number(order.subtotalAmount);
    const sellerPayoutAmount = Number(order.sellerPayoutAmount);
    const commissionAmount = Number(order.commissionAmount);
    const fallbackPayout = unsettledItems.reduce((sum, item) => sum + Number(item.price) * item.quantity, 0);
    const payoutPool = sellerPayoutAmount > 0 ? sellerPayoutAmount : fallbackPayout;
    const payoutsBySeller = new Map;
    for (const item of unsettledItems) {
      const grossItemAmount = Number(item.price) * item.quantity;
      const itemPayout = subtotalAmount > 0 && sellerPayoutAmount > 0 ? roundMoney(grossItemAmount / subtotalAmount * payoutPool) : grossItemAmount;
      const sellerId = item.product.sellerId;
      const sellerPayout = payoutsBySeller.get(sellerId) || { amount: 0, items: [] };
      sellerPayout.amount = roundMoney(sellerPayout.amount + itemPayout);
      sellerPayout.items.push(item);
      payoutsBySeller.set(sellerId, sellerPayout);
    }
    for (const [sellerId, payout] of payoutsBySeller.entries()) {
      const amountInKobo = Math.round(payout.amount * 100);
      await tx.wallet.upsert({
        where: { userId: sellerId },
        update: { balance: { increment: amountInKobo } },
        create: { userId: sellerId, balance: amountInKobo }
      });
      await tx.orderItem.updateMany({
        where: { id: { in: payout.items.map((item) => item.id) } },
        data: { sellerSettledAt: new Date }
      });
    }
    await tx.orderActivity.create({
      data: {
        orderId,
        type: "ORDER_STATUS_UPDATED",
        message: "Seller wallets settled after delivery confirmation",
        metadata: {
          settledItems: unsettledItems.map((item) => ({
            orderItemId: item.id,
            sellerId: item.product.sellerId,
            grossAmount: Number(item.price) * item.quantity
          })),
          commissionAmount,
          sellerPayoutAmount: payoutPool,
          payoutsBySeller: Array.from(payoutsBySeller.entries()).map(([sellerId, payout]) => ({
            sellerId,
            amount: payout.amount
          }))
        }
      }
    });
  });
}
function roundMoney(amount) {
  return Math.round(amount * 100) / 100;
}

