async function getAuthenticatedUser(token) {
  if (!token) {
    return null;
  }
  const { session, user } = await validateSessionToken(token);
  return session && user ? user : null;
}
async function canAccessOrder(orderId, userId) {
  const order = await db.order.findUnique({
    where: { id: orderId },
    include: {
      items: {
        include: { product: true }
      }
    }
  });
  return Boolean(order && isOrderParticipant(order, userId));
}
function isOrderParticipant(order, userId) {
  return order.buyerId === userId || order.items.some((item) => item.product.sellerId === userId);
}

